package org.eclipse.rdf4j.sail.lmdb.evaluation;

import java.util.List;

/**
 * The one ranking rule of the native engine. Given admitted candidates in registry order it prices each with the static
 * prior, removes every candidate another admitted candidate structurally dominates, removes every candidate whose whole
 * interval lies above another's, and selects the lowest expected price among the survivors. Registry order breaks exact
 * ties only. A last-resort candidate competes only when no ordinary candidate is admitted.
 * <p>
 * The rule is a pure function of its inputs: no clock, no learned state, no declaration-order dependence beyond the
 * final tie break. That is what makes a decision reproducible and explainable.
 */
final class LmdbNativeSelector {

	/**
	 * The outcome of ranking: the winner's index (or -1), and per candidate its priced interval, expected price and
	 * what eliminated it (null while eligible).
	 */
	record Ranking(int winner, LmdbNativeWork[] nanos, double[] expectedNanos, String[] eliminatedBy,
			String reason) {
	}

	private LmdbNativeSelector() {
	}

	static <T> Ranking rank(List<LmdbNativeCandidate<T>> candidates, LmdbNativeStaticPrior prior,
			double sliceRows) {
		return rank(candidates, prior, sliceRows, false);
	}

	static <T> Ranking rank(List<LmdbNativeCandidate<T>> candidates, LmdbNativeStaticPrior prior,
			double sliceRows, boolean distinctConsumer) {
		return rank(candidates, prior, sliceRows, Math.max(2, LmdbNativeKernelExecution.parallelProposalWorkers()),
				distinctConsumer);
	}

	static <T> Ranking rank(List<LmdbNativeCandidate<T>> candidates, LmdbNativeStaticPrior prior,
			double sliceRows, int parallelWorkers) {
		return rank(candidates, prior, sliceRows, parallelWorkers, false);
	}

	/**
	 * A distinct-key budget does not bound a duplicate-producing candidate's rows. Only the first key can always be
	 * taken from its first row. Later keys need a candidate that certifies uniqueness for this decision's output keys;
	 * {@code forSlice} additionally requires its usable output-cardinality estimate before prorating work.
	 */
	static double consumableRows(LmdbNativeCostQuote quote, double sliceRows, boolean distinctConsumer) {
		return distinctConsumer && sliceRows > 1D && !quote.distinct() ? -1D : sliceRows;
	}

	static <T> Ranking rank(List<LmdbNativeCandidate<T>> candidates, LmdbNativeStaticPrior prior,
			double sliceRows, int parallelWorkers, boolean distinctConsumer) {
		int n = candidates.size();
		LmdbNativeWork[] nanos = new LmdbNativeWork[n];
		double[] expected = new double[n];
		int[] candidateWorkers = new int[n];
		String[] eliminatedBy = new String[n];
		if (n == 0) {
			return new Ranking(-1, nanos, expected, eliminatedBy, "No strategy was admitted at this decision point");
		}
		boolean ordinary = false;
		boolean bounded = false;
		for (int i = 0; i < n; i++) {
			LmdbNativeCandidate<T> candidate = candidates.get(i);
			LmdbNativeCostVector vector = candidate.quote()
					.forSlice(consumableRows(candidate.quote(), sliceRows, distinctConsumer));
			double quotedWorkers = candidate.quote().startup().expected(LmdbNativeCostVector.Feature.WORKER_START);
			candidateWorkers[i] = quotedWorkers > 0D ? Math.max(1, (int) Math.ceil(quotedWorkers))
					: LmdbNativeCandidate.isParallel(candidate.id()) ? parallelWorkers : 0;
			double fixed = LmdbNativeStaticPrior.fixedNanos(candidates.get(i).id());
			LmdbNativeWork priced = prior.price(vector);
			nanos[i] = LmdbNativeWork.between(priced.low() + fixed, priced.high() + fixed);
			expected[i] = prior.expected(vector) + fixed;
			ordinary |= !candidates.get(i).lastResort();
			bounded |= !candidates.get(i).lastResort() && nanos[i].known();
		}
		for (int i = 0; i < n; i++) {
			if (ordinary && candidates.get(i).lastResort()) {
				eliminatedBy[i] = "Last resort: considered only when no ordinary candidate is admitted";
			} else if (bounded && !nanos[i].known()) {
				// An unbounded quote has no ceiling to compare; its floor is not a price. It competes only when no
				// candidate could price itself at all.
				eliminatedBy[i] = "Unpriced: quotes no finite ceiling while priced candidates exist";
			}
		}
		// Structural edges are evaluated simultaneously. A dominated admitted strategy still establishes its own
		// dominance edges; otherwise A -> B -> C depends on whether B was visited before C.
		boolean[] structurallyEligible = new boolean[n];
		for (int i = 0; i < n; i++) {
			structurallyEligible[i] = eliminatedBy[i] == null;
		}
		for (int i = 0; i < n; i++) {
			if (!structurallyEligible[i]) {
				continue;
			}
			String id = candidates.get(i).id();
			String base = LmdbNativeCandidate.baseId(id);
			for (int j = 0; j < n; j++) {
				if (j == i || !structurallyEligible[j]) {
					continue;
				}
				if (candidates.get(j).dominates().contains(id) || candidates.get(j).dominates().contains(base)) {
					eliminatedBy[i] = "Structurally dominated by " + candidates.get(j).id();
					break;
				}
			}
		}
		// parallel cut: a multi-threaded candidate must cut the best serial candidate's expected price by the share
		// its worker count demands (30 % on four workers, 50 % on eight), or the serial candidate keeps the cores
		double serialBest = Double.POSITIVE_INFINITY;
		for (int i = 0; i < n; i++) {
			if (eliminatedBy[i] == null && nanos[i].known()
					&& candidateWorkers[i] == 0) {
				serialBest = Math.min(serialBest, expected[i]);
			}
		}
		if (Double.isFinite(serialBest)) {
			for (int i = 0; i < n; i++) {
				double fraction = LmdbNativeStaticPrior.requiredParallelFraction(candidateWorkers[i]);
				if (eliminatedBy[i] == null && candidateWorkers[i] > 0
						&& expected[i] > fraction * serialBest) {
					eliminatedBy[i] = String.format(
							"Parallel: expected %.0f ns is %.0f %% of the best serial price (%.0f ns), above the %.0f %% cut required on %d workers",
							expected[i], 100D * expected[i] / serialBest, serialBest, 100D * fraction,
							candidateWorkers[i]);
				}
			}
		}
		// interval dominance: a rival whose whole price lies below this candidate's whole price
		for (int i = 0; i < n; i++) {
			if (eliminatedBy[i] != null) {
				continue;
			}
			for (int j = 0; j < n; j++) {
				if (j == i || eliminatedBy[j] != null && !eliminatedBy[j].startsWith("Priced")) {
					continue;
				}
				if (nanos[j].beats(nanos[i])) {
					eliminatedBy[i] = String.format("Priced above %s (%.0f ns ceiling below %.0f ns floor)",
							candidates.get(j).id(), nanos[j].high(), nanos[i].low());
					break;
				}
			}
		}
		int winner = -1;
		int eligible = 0;
		for (int i = 0; i < n; i++) {
			if (eliminatedBy[i] != null) {
				continue;
			}
			eligible++;
			if (winner < 0 || expected[i] < expected[winner]) {
				winner = i;
			}
		}
		String reason;
		if (winner < 0) {
			reason = "No candidate survived elimination";
		} else if (eligible == 1 && n == 1) {
			reason = "Only admitted candidate";
		} else if (eligible == 1) {
			reason = "Only candidate left after elimination";
		} else {
			reason = String.format("Lowest expected price (%.0f ns) among %d eligible candidates",
					expected[winner], eligible);
		}
		return new Ranking(winner, nanos, expected, eliminatedBy, reason);
	}
}
